window.PROVINCE_ALIASES={"贵州":["贵州","黔","多彩贵州","贵州省"],"山西":["山西","晋","三晋","山西省"],"浙江":["浙江","浙","诗画浙江","浙江省"],"新疆":["新疆","疆","大美新疆","新疆维吾尔自治区"],"湖南":["湖南","湘","锦绣潇湘","湖南省"],"江西":["江西","赣","风景独好","江西省"],"四川":["四川","川","天府之国","四川省"],"湖北":["湖北","鄂","荆楚大地","湖北省"],"广东":["广东","粤","活力广东","广东省"],"山东":["山东","鲁","好客山东","山东省"]},window.generateDrivingRoute=function(province,totalDays){const pData=window.PROVINCE_DRIVING[province];if(!pData)return null;if(pData.templates[totalDays])return{...pData.templates[totalDays],source:"template",matchedDays:totalDays,actualDays:totalDays};const cities=Object.keys(pData.cities),capital=pData.capital,maxCities=Math.min(totalDays,cities.length);function getDist(a,b){if(a===b)return{km:0,minutes:0,route:""};const key1=a+"-"+b,key2=b+"-"+a;if(pData.distances[key1])return pData.distances[key1];if(pData.distances[key2])return pData.distances[key2];const c1=pData.cities[a].coord,c2=pData.cities[b].coord,toRad=d=>d*Math.PI/180,dLat=toRad(c2[1]-c1[1]),dLng=toRad(c2[0]-c1[0]),h=Math.sin(dLat/2)**2+Math.cos(toRad(c1[1]))*Math.cos(toRad(c2[1]))*Math.sin(dLng/2)**2,km=12742*Math.asin(Math.sqrt(h))*1.3;return{km:Math.round(km),minutes:Math.round(km/80*60),route:"省道/国道"}}const visited=[capital];let current=capital;for(;visited.length<maxCities;){let nearest=null,nearestDist=1/0;for(const c of cities){if(visited.includes(c))continue;const d=getDist(current,c);d.km<nearestDist&&(nearestDist=d.km,nearest=c)}if(!nearest)break;visited.push(nearest),current=nearest}const dayPlan=visited.map((city,i)=>{const prev=0===i?capital:visited[i-1],drive=0===i?{km:0,minutes:0,route:"出发"}:getDist(prev,city),cityInfo=pData.cities[city];return{day:i+1,city:0===i?city:prev+"→"+city,theme:cityInfo.intro,drive:drive,activities:cityInfo.highlights,stayCity:city,hours:Math.max(7,Math.round(8+drive.minutes/60))}});return{name:province+totalDays+"日智能自驾",tagline:"智能编排 · 覆盖"+visited.length+"城",cities:visited,dayPlan:dayPlan,source:"algorithm",actualDays:totalDays}};